  "ticket_id": "4ee7-2207",
  "items": [
    {
      "original_text": "When the orchestrator runs harvest-worktree.sh <worktree-branch>, a clean worktree merge completes in a single invocation \u2014 no retry cycles, no manual re-recording of test or review status",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable system behavior where a specific operation completes reliably without retries, a property that persists after the work is done"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When a worktree branch's test-gate-status or review-status is missing or failed, harvest-worktree.sh refuses to merge and exits non-zero with a diagnostic message",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system behavior (merge refusal and exit code) that persists after implementation whenever conditions are met"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When the merge produces conflicts in files other than .test-index, harvest-worktree.sh aborts the merge and exits non-zero \u2014 conflicted merges never receive attestation",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes durable system behavior (conflict handling and attestation policy) that persists after implementation, phrased as ongoing behavior despite conditional framing"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When two worktree branches both add entries to .test-index, the merge resolves automatically without manual conflict resolution (union merge driver)",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 5,
        "rationale": "describes a durable system behavior where merges automatically resolve using union merge driver, persisting after implementation"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "When harvest-worktree.sh attests test/review status, the attestation includes the source worktree ID so the trust chain is auditable via the status file",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable system behavior where attestations persistently include worktree ID information for auditability"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    },
    {
      "original_text": "The pre-commit test gate and review gate hooks are not modified \u2014 gate integrity is preserved by the existing validation logic, not weakened by new bypass paths",
      "original_section": "SC",
      "classification": {
        "label": "end-state",
        "ranking": 4,
        "rationale": "describes a durable property of the system (gate integrity preserved without bypass paths) that persists after the work is complete"
      },
      "user_decision": "auto",
      "post_migration_section": "SC"
    }
  ]
}
